import sys,json,time,ssl,urllib.request,urllib.parse,urllib.error,fcntl
from pathlib import Path
from html.parser import HTMLParser
run,mode,url=sys.argv[1:]
if run not in ['recency_a','recency_b','language'] or mode != 'text': raise SystemExit('Invalid run/mode')
if urllib.parse.urlparse(url).hostname!='zotonicwww2.test': raise SystemExit('Stay on the supplied site')
folder=Path('/tmp/zotonic-markdown-trial')/run
folder.mkdir(exist_ok=True)
lock=(folder/'fetch.lock').open('w')
fcntl.flock(lock,fcntl.LOCK_EX)
log=folder/'requests.jsonl'
count=len(log.read_text().splitlines()) if log.exists() else 0
if count>=8: raise SystemExit('Eight-request trial budget exhausted')
t=time.monotonic()
try:
    r=urllib.request.urlopen(url,context=ssl._create_unverified_context(),timeout=20)
except urllib.error.HTTPError as e: r=e
body=r.read(); elapsed=time.monotonic()-t
ctype=r.headers.get('content-type',''); text=body.decode('utf-8','replace')
record=dict(n=count+1,url=url,final_url=r.url,status=r.status,bytes=len(body),seconds=round(elapsed,4),content_type=ctype)
with log.open('a') as f: f.write(json.dumps(record)+'\n')
(folder/f'{count+1}.body').write_bytes(body)
(folder/f'{count+1}.headers.json').write_text(json.dumps(dict(r.headers),indent=2))
class Visible(HTMLParser):
    def __init__(self): super().__init__(convert_charrefs=True); self.skip=0;self.out=[];self.links=[]
    def handle_starttag(self,tag,attrs):
        attrs=dict(attrs)
        if tag in ['head','script','style','svg']: self.skip+=1
        if self.skip:return
        if tag in ['p','div','li','h1','h2','h3','section','br','tr']:self.out.append('\n')
        if tag=='a':self.links.append(attrs.get('href'))
        if tag=='img' and attrs.get('alt'):self.out.append('[Image: '+attrs['alt']+']')
    def handle_endtag(self,tag):
        if tag in ['head','script','style','svg']: self.skip=max(0,self.skip-1);return
        if self.skip:return
        if tag=='a' and self.links:
            link=self.links.pop()
            if link:self.out.append(' ['+urllib.parse.urljoin(url,link)+'] ')
    def handle_data(self,data):
        if not self.skip:self.out.append(data)
if mode=='text' and 'html' in ctype:
    p=Visible();p.feed(text);text='\n'.join(x.strip() for x in ''.join(p.out).splitlines() if x.strip())
print('URL:',r.url,'STATUS:',r.status)
if mode=='http':print('HEADERS:',json.dumps(dict(r.headers)))
print(text[:80000])
if len(text)>80000:print('[Display truncated at 80,000 characters]')
